/**
 * What a track's surroundings are made of, in game pixels: read from a file for the real-world
 * Reims map (written by scripts/import-reims.mjs), generated by sceneryGen.ts for the invented
 * tracks, and drawn by MapRenderer. No Phaser in here, so the generator can be tested on its own.
 */
export interface SceneryData {
  source: string;
  water: number[][];
  vegetation: [number, number[]][];
  roads: [number, number, number, number[]][]; // class (0 motorway, 1 road, 2 path), width, bridge, line
  rails: [number, number, number[]][]; // width, bridge, line
  buildings: [number, number, number[]][]; // height (m), kind (0 house, 1 church, 2 industrial), ring
  bridges: [string, number[]][];
  /** Bridges over the canal: x, y on the centre line, kind (0 own name, 1 street it carries, 2 railway), name. */
  labels?: [number, number, number, string][];
  /** Street names written along the streets: x, y, angle (milliradians), font size, name, available length (px). */
  streets?: [number, number, number, number, string, number][];
  /** Sports grounds: kind (0 pitch, 1 tennis, 2 court, 3 track, 4 pool), ring. */
  sports?: [number, number[]][];
  cemeteries?: number[][];
  /** Single trees and bushes: x, y, crown radius, colour (the invented tracks place every tree). */
  trees?: [number, number, number, number][];
  /** Lily pads floating in the channel: x, y, radius. */
  pads?: [number, number, number, number?][]; // x, y, radius, heading (milliradians; dinghies)
  /** Looks that differ between places. */
  style?: {
    /** Colour of the edge between towpath and water (default: quay stone). */
    quay?: number;
    /** Share of terracotta (rather than slate) house roofs, 0..1. */
    tiled?: number;
    /** What floats in the slack water by the banks (default lily pads). */
    pads?: 'lily' | 'ice' | 'rock' | 'dinghy';
  };
}

/** Width of the quay or towpath drawn along both banks (px). */
export const TOWPATH = 45;

/** Building kinds: IGN's (house, church, industrial) and three used by the invented tracks. */
export const BUILDING = { house: 0, church: 1, industrial: 2, tank: 3, container: 4, shack: 5 } as const;
